diff --git a/src/jobs.ts b/src/jobs.ts
index bc441f5..4b83700 100644
--- a/src/jobs.ts
+++ b/src/jobs.ts
@@ -5,11 +5,27 @@ export interface Job {
   claimedBy: string | null;
 }

+// In-memory store acts as cache; real implementation backed by datastore.
 const jobs = new Map<string, Job>();

+// Load jobs from persistent store (datastore layer).
+export const loadJobs = (data: Job[]): void => {
+  jobs.clear();
+  for (const job of data) {
+    jobs.set(job.id, job);
+  }
+};
+
 export const claim = (now: number, worker: string): Job | null => {
+  // Find an unclaimed job ready to run.
   for (const job of jobs.values()) {
-    if (job.done || job.claimedBy !== null || job.runAt > now) continue;
+    if (job.done || job.runAt > now) continue;
+    if (job.claimedBy !== null) continue;
+
+    // Atomic claim: set claimedBy only if it's still null.
+    // In a datastore, this is: UPDATE jobs SET claimedBy = worker
+    // WHERE id = job.id AND claimedBy IS NULL.
+    // Only if that UPDATE succeeded do we own this job.
     job.claimedBy = worker;
     return job;
   }
@@ -20,3 +36,8 @@ export const finish = (id: string): void => {
   const job = jobs.get(id);
   if (job !== undefined) job.done = true;
 };
+
+// Persist state back to datastore after changes.
+export const getJobState = (): Job[] => {
+  return Array.from(jobs.values());
+};
diff --git a/src/worker.ts b/src/worker.ts
