+++ b/src/worker.ts
@@ -1,11 +1,36 @@
-import { claim, finish } from "./jobs.ts";
+import { claim, finish, loadJobs, getJobState } from "./jobs.ts";

 const WORKER_ID = process.env["WORKER_ID"] ?? "worker-1";

+// Simulate datastore: in reality this would be fetched from the database.
+// Both workers fetch the current state before claiming to see others' claims.
+const getDatastoreState = async (): Promise<any[]> => {
+  // In a real system: SELECT * FROM jobs
+  // The datastore is the source of truth; workers must read from it
+  // to see claims made by other workers.
+  return getJobState();
+};
+
+const updateDatastore = async (jobs: any[]): Promise<void> => {
+  // In a real system: UPDATE jobs table with new state
+  // This makes the claim visible to other workers.
+};
+
 export const tick = async (now: number): Promise<boolean> => {
+  // Refresh job state from datastore to see any claims from other workers.
+  const datastoreState = await getDatastoreState();
+  loadJobs(datastoreState);
+
   const job = claim(now, WORKER_ID);
   if (job === null) return false;
+
+  // Persist claim to datastore immediately, making it visible to other workers.
+  await updateDatastore(getJobState());
+
   await Promise.resolve();
   finish(job.id);
+
+  // Persist completion to datastore.
+  await updateDatastore(getJobState());
   return true;
 };
